【主要应用】字符串前缀查询、单词检索、异或最值、AC 自动机前置、字符串排序。
【应用方式】每个节点代表一个前缀，边代表字符；插入与查询 O(L)；01 字典树求异或最值；可持久化字典树处理区间查询。
【模板代码】
```cpp
// 字典树
int ch[N][26], cnt[N], tot = 1;
void insert(string s) {
    int u = 1;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) ch[u][v] = ++tot;
        u = ch[u][v];
    }
    cnt[u]++;
}
bool query(string s) {
    int u = 1;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) return false;
        u = ch[u][v];
    }
    return cnt[u] > 0;
}

// 01 字典树求最大异或
int ch[N][2], tot = 1;
void insert(int x) {
    int u = 1;
    for (int i = 30; i >= 0; i--) {
        int v = (x >> i) & 1;
        if (!ch[u][v]) ch[u][v] = ++tot;
        u = ch[u][v];
    }
}
int query(int x) {
    int u = 1, res = 0;
    for (int i = 30; i >= 0; i--) {
        int v = (x >> i) & 1;
        if (ch[u][v ^ 1]) res |= 1 << i, u = ch[u][v ^ 1];
        else u = ch[u][v];
    }
    return res;
}
```

