【主要应用】字符串匹配、最小循环节、前缀函数、扩展 KMP、Z 函数、字符串删除。
【应用方式】next 数组表示最长公共前后缀；匹配时利用 next 跳转；最小循环节 = n - next[n]；exKMP 求每个后缀与原串的 LCP。
【模板代码】
```cpp
// KMP
int nxt[N];
void get_next(string s) {
    nxt[0] = -1;
    int i = 0, j = -1;
    while (i < s.size()) {
        if (j == -1 || s[i] == s[j]) nxt[++i] = ++j;
        else j = nxt[j];
    }
}
void kmp(string s, string t) {
    int i = 0, j = 0;
    while (i < s.size()) {
        if (j == -1 || s[i] == t[j]) i++, j++;
        else j = nxt[j];
        if (j == t.size()) {
            printf("%d\n", i - j + 1);
            j = nxt[j];
        }
    }
}

// 扩展 KMP（Z 函数）
void z_function(string s) {
    int n = s.size();
    vector<int> z(n);
    for (int i = 1, l = 0, r = 0; i < n; i++) {
        if (i <= r) z[i] = min(r - i + 1, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] - 1 > r) l = i, r = i + z[i] - 1;
    }
}
```

