【主要应用】多模式串匹配、文本生成器、病毒检测、单词统计、字符串 DP。
【应用方式】Trie 树 + fail 指针；fail 指针指向最长后缀；匹配时沿 fail 跳转统计；fail 树 + 拓扑排序统计出现次数；ACAM + DP 处理限制。
【模板代码】
```cpp
// AC 自动机
int ch[N][26], fail[N], cnt[N], tot = 1;
void insert(string s) {
    int u = 1;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) ch[u][v] = ++tot;
        u = ch[u][v];
    }
    cnt[u]++;
}
void build() {
    queue<int> q;
    for (int i = 0; i < 26; i++) {
        if (ch[1][i]) fail[ch[1][i]] = 1, q.push(ch[1][i]);
        else ch[1][i] = 1;
    }
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = 0; i < 26; i++) {
            if (ch[u][i]) fail[ch[u][i]] = ch[fail[u]][i], q.push(ch[u][i]);
            else ch[u][i] = ch[fail[u]][i];
        }
    }
}
int query(string s) {
    int u = 1, res = 0;
    for (char c : s) {
        u = ch[u][c - 'a'];
        for (int j = u; j > 1 && cnt[j] != -1; j = fail[j])
            res += cnt[j], cnt[j] = -1;
    }
    return res;
}
```

