【主要应用】后缀排序、最长公共前缀、本质不同子串计数、重复子串、字符串匹配。
【应用方式】后缀数组 SA + height 数组；倍增法或 SA-IS 构造；height 表示相邻后缀 LCP；结合单调栈、并查集、RMQ 处理问题。
【模板代码】
```cpp
// 后缀数组（倍增法）
int sa[N], rk[N], tmp[N], height[N];
void build_sa(string s) {
    int n = s.size();
    for (int i = 0; i < n; i++) sa[i] = i, rk[i] = s[i];
    for (int k = 1; k < n; k <<= 1) {
        sort(sa, sa + n, [&](int i, int j) {
            return rk[i] == rk[j] ? rk[i + k] < rk[j + k] : rk[i] < rk[j];
        });
        tmp[sa[0]] = 0;
        for (int i = 1; i < n; i++)
            tmp[sa[i]] = tmp[sa[i-1]] + (rk[sa[i]] != rk[sa[i-1]] || rk[sa[i]+k] != rk[sa[i-1]+k]);
        for (int i = 0; i < n; i++) rk[i] = tmp[i];
    }
}
void get_height(string s) {
    int n = s.size(), k = 0;
    for (int i = 0; i < n; i++) {
        if (rk[i] == 0) continue;
        if (k) k--;
        int j = sa[rk[i] - 1];
        while (i + k < n && j + k < n && s[i+k] == s[j+k]) k++;
        height[rk[i]] = k;
    }
}
```

