【主要应用】本质不同子串计数、子串出现次数、最长公共子串、字符串 DP、SAM 上拓扑排序。
【应用方式】SAM 每个状态表示一组 endpos 相同的子串；len 表示最长子串长度，link 指向后缀；parent 树 + 拓扑排序统计出现次数；SAM 上 DP 求第 k 小子串。
【模板代码】
```cpp
// 后缀自动机（SAM）
struct SAM {
    int ch[N][26], len[N], link[N], cnt[N], tot = 1, last = 1;
    void extend(int c) {
        int cur = ++tot, p = last;
        len[cur] = len[p] + 1;
        while (p && !ch[p][c]) ch[p][c] = cur, p = link[p];
        if (!p) link[cur] = 1;
        else {
            int q = ch[p][c];
            if (len[q] == len[p] + 1) link[cur] = q;
            else {
                int clone = ++tot;
                len[clone] = len[p] + 1;
                link[clone] = link[q];
                memcpy(ch[clone], ch[q], sizeof(ch[q]));
                while (p && ch[p][c] == q) ch[p][c] = clone, p = link[p];
                link[q] = link[cur] = clone;
            }
        }
        last = cur;
        cnt[cur] = 1;
    }
    void build(string s) { for (char c : s) extend(c - 'a'); }
    // 统计出现次数
    void count() {
